/** The line a reply shows while the model works, before it has anything to show. */
function ThinkingIndicator({
  className,
  label = 'Thinking…',
}: {
  className?: string
  /** @default 'Thinking…' */
  label?: string
}) {
  return (
    <Marker data-slot='thinking-indicator' className={className}>
      <MarkerIcon>
        <IconPlaceholder
          lucide='Loader2Icon'
          tabler='IconLoader'
          hugeicons='Loading03Icon'
